1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./scenario.js";
3	
4	const REFUSED = 1;
5	
6	function scenarioFromStdin(): Scenario {
7	  return JSON.parse(readFileSync(0, "utf8")) as Scenario;
8	}
9	
10	/**
11	 * How a refusal is described to whoever ran the CLI. The MHPCO states its
12	 * refusals as messages -- "does not insure items of type ...", "policy does
13	 * not cover ..." -- so a refusal that carries one is reported by it.
14	 *
15	 * A refusal that carries no message is still owed a description: the spec
16	 * requires one on stderr for every non-zero exit, so there is no case in
17	 * which the CLI may fall silent. Reading the message off an assumed shape
18	 * would produce exactly that silence, which is why the description is
19	 * derived here rather than asserted.
20	 */
21	function refusalDescription(refusal: unknown): string {
22	  return refusal instanceof Error ? refusal.message : String(refusal);
23	}
24	
25	/**
26	 * The claim-office adapter: a scenario is read from stdin and its results
27	 * written to stdout. A refusal by the MHPCO -- an item it does not insure,
28	 * a damage the policy does not cover, a malformed damage report -- is not a
29	 * result, so it is reported on stderr and exits non-zero with no results
30	 * written to stdout.
31	 *
32	 * Every answer the MHPCO could not produce is reported the same way. The
33	 * spec gives all four of its refusal grounds one outcome and distinguishes
34	 * no other kind of non-answer, so the adapter makes no distinction either:
35	 * which grounds exist is knowledge held by the rules that raise them, not
36	 * here.
37	 */
38	function main(): void {
39	  try {
40	    process.stdout.write(`${JSON.stringify(runScenario(scenarioFromStdin()))}\n`);
41	  } catch (refusal) {
42	    process.stderr.write(`${refusalDescription(refusal)}\n`);
43	    process.exitCode = REFUSED;
44	  }
45	}
46	
47	main();
