1	import type { Item } from "./policy.js";
2	
3	/**
4	 * Matching an incident's damage entries to the insured items they hit.
5	 *
6	 * This is its own decision, separate from what a damage settles at: it
7	 * answers "which covered item was this?", not "what does the MHPCO pay?".
8	 * Each entry consumes a distinct insured item, so an incident naming a type
9	 * more often than the policy covers it is refused rather than settled -- an
10	 * entry with no insured item left to consume has nothing to claim against.
11	 *
12	 * Which of several alike items an entry consumes is a decision in its own
13	 * right, and the MHPCO settles it by order: an entry takes the first item of
14	 * its type the policy still has unconsumed. An incident names a type, never
15	 * a particular sword, so the MHPCO has no other ground to choose on. The
16	 * choice is unobservable only while alike items settle alike; two swords at
17	 * different enchantment levels would make it visible, and it is stated here
18	 * by name so that revising it means revising this rule rather than
19	 * discovering it in what the matching happens to do.
20	 */
21	export function damagedItems(
22	  items: readonly Item[],
23	  itemTypes: readonly string[],
24	): readonly Item[] {
25	  const unconsumed = [...items];
26	  return itemTypes.map((itemType) => {
27	    const hit = unconsumed.findIndex((item) => item.type === itemType);
28	    if (hit === -1) {
29	      throw new Error(
30	        `This policy does not cover an item of type "${itemType}"`,
31	      );
32	    }
33	    return unconsumed.splice(hit, 1)[0];
34	  });
35	}
