1	/** The MHPCO's shared vocabulary for what a policy covers. */
2	
3	export interface Customer {
4	  readonly yearsWithMHPCO: number;
5	}
6	
7	export interface Item {
8	  readonly type: string;
9	  readonly material?: string;
10	  readonly enchantment?: number;
11	  readonly cursed?: boolean;
12	}
13	
14	/**
15	 * An item that carries no enchantment level at all -- a rune, a moonstone --
16	 * counts as unenchanted rather than as unknown. This is a fact about the
17	 * vocabulary, not about any one rule: the premium side and the claim side
18	 * both rely on it while setting their own thresholds independently.
19	 */
20	const UNENCHANTED = 0;
21	
22	export function enchantmentLevelOf(item: Item): number {
23	  return item.enchantment ?? UNENCHANTED;
24	}
25

1	import { insuranceValueOf } from "./item-price-rules.js";
2	import type { Item } from "./policy.js";
3	
4	/** The policy's insurance sum is the sum of its items' insurance values. */
5	export function insuranceSum(items: readonly Item[]): number {
6	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
7	}
8	
9	/** The total payout per policy is capped at twice the insurance sum. */
10	const PAYOUT_CAP_MULTIPLE = 2;
11	
12	export function payoutCap(items: readonly Item[]): number {
13	  return insuranceSum(items) * PAYOUT_CAP_MULTIPLE;
14	}
