1	import type { Item } from "./policy.js";
2	import type { ItemPricing } from "./premium-contribution.js";
3	import { combinedPricings } from "./premium-contribution.js";
4	import { basePremiumOf } from "./price-list.js";
5	import { riskSurchargeOf } from "./risk-surcharge.js";
6	
7	/**
8	 * What one main item contributes: the price list's base premium, and the
9	 * item's own risk surcharges, which scale that same base premium.
10	 */
11	function priceMainItem(item: Item): ItemPricing {
12	  const basePremium = basePremiumOf(item);
13	  return {
14	    basePremium,
15	    riskSurcharges: riskSurchargeOf(item, basePremium),
16	  };
17	}
18	
19	export function priceMainItems(mainItems: readonly Item[]): ItemPricing {
20	  return combinedPricings(mainItems.map(priceMainItem));
21	}
