1	import { priceItems } from "./item-price-rules.js";
2	import type { Customer, Item } from "./policy.js";
3	import { policyWideAdjustment } from "./policy-modifier.js";
4	import { premiumRoundedInMHPCOsFavour } from "./rounding.js";
5	
6	/** Every premium carries the MHPCO's flat processing fee. */
7	const PROCESSING_FEE = 5;
8	
9	/**
10	 * Item-specific modifiers apply to the base premium of the affected item;
11	 * policy-wide modifiers apply to the policy base premium; the processing
12	 * fee is added at the very end, so it is part of the amount that is
13	 * rounded.
14	 *
15	 * Every intermediate amount stays a fraction; only this final premium is
16	 * stated in whole G.
17	 */
18	export function quote(
19	  customer: Customer,
20	  items: readonly Item[],
21	  previousContracts: number,
22	): number {
23	  const { basePremium, riskSurcharges } = priceItems(items);
24	
25	  const premium =
26	    basePremium +
27	    riskSurcharges +
28	    policyWideAdjustment({ customer, previousContracts }, basePremium) +
29	    PROCESSING_FEE;
30	
31	  return premiumRoundedInMHPCOsFavour(premium);
32	}
